{
  "name": "Dimensionamento de Infraestrutura Elétrica - NBR 5410",
  "description": "Calculadora profissional para dimensionamento de eletrocalhas, leitos e eletrodutos baseada na norma NBR 5410, com suporte a múltiplos cabos e ajuste dinâmico de dimensões."
}

export type CableType = 'Força' | 'Comando' | 'Sinal';
export type CableForm = 'Singelo' | 'Multipolar';

export interface CableData {
  id: string;
  category: CableType;
  form: CableForm;
  gauge: number; // mm²
  quantity: number;
  diameter: number; // mm
  area: number; // mm²
}

export interface DimensionResult {
  type: 'Eletrocalha' | 'Leito' | 'Eletroduto';
  aba: number; // Height in mm
  largura: number; // Width in mm
  ocupacao: number; // Percentage
  areaTotalOcupada: number;
}

export interface StandardGauge {
  size: number;
  diameter: number; // Based on Sintenax Flex / Prysmian for Power
}

import { StandardGauge } from './types';

// Tabelas de Diâmetros Externos (D.E.) Aproximados - Baseados em NBR e Catálogos Prysmian/Poliron
export const CABLE_GAUGES: StandardGauge[] = [
  { size: 0.5, diameter: 2.2 },
  { size: 0.75, diameter: 2.4 },
  { size: 1.0, diameter: 2.6 },
  { size: 1.5, diameter: 3.0 },
  { size: 2.5, diameter: 3.7 },
  { size: 4.0, diameter: 4.2 },
  { size: 6.0, diameter: 4.8 },
  { size: 10.0, diameter: 6.0 },
  { size: 16.0, diameter: 7.4 },
  { size: 25.0, diameter: 9.3 },
  { size: 35.0, diameter: 10.7 },
  { size: 50.0, diameter: 12.7 },
  { size: 70.0, diameter: 14.6 },
  { size: 95.0, diameter: 17.1 },
  { size: 120.0, diameter: 19.0 },
  { size: 150.0, diameter: 21.2 },
  { size: 185.0, diameter: 23.6 },
  { size: 240.0, diameter: 26.9 },
  { size: 300.0, diameter: 30.1 }
];

// Medidas padrão de Eletrocalhas e Leitos (mm)
export const STANDARD_ABAS = [50, 75, 100];
export const STANDARD_WIDTHS = [50, 100, 150, 200, 250, 300, 400, 500, 600, 700, 800];

// Medidas padrão de Eletrodutos (Polegadas -> Diâmetro interno mm)
// Aproximação para SCH 40 conforme NBR
export const CONDUIT_SIZES = [
  { label: '1/2"', internalArea: 196 },
  { label: '3/4"', internalArea: 342 },
  { label: '1"', internalArea: 564 },
  { label: '1 1/4"', internalArea: 984 },
  { label: '1 1/2"', internalArea: 1345 },
  { label: '2"', internalArea: 2216 },
  { label: '2 1/2"', internalArea: 3166 },
  { label: '3"', internalArea: 4899 },
  { label: '4"', internalArea: 8494 }
];

export const OCCUPANCY_LIMITS = {
  CONDUIT: {
    ONE: 0.53,
    TWO: 0.31,
    THREE_PLUS: 0.40
  },
  TRAY: 0.40, // General default for trays/ladders (NBR 5410 Tab 62/69 logic)
  LADDER: 0.40
};

import { CableData, DimensionResult, CableType } from '../types';
import { STANDARD_WIDTHS, OCCUPANCY_LIMITS, CONDUIT_SIZES } from '../constants';

export const calculateCableArea = (diameter: number): number => {
  return (Math.PI * Math.pow(diameter, 2)) / 4;
};

export const getSmallestWidth = (requiredArea: number, aba: number): number => {
  for (const width of STANDARD_WIDTHS) {
    if (width * aba >= requiredArea) {
      return width;
    }
  }
  return STANDARD_WIDTHS[STANDARD_WIDTHS.length - 1]; // Return max if none fit
};

export const getConduitSize = (totalArea: number, cableCount: number): string => {
  let limit = OCCUPANCY_LIMITS.CONDUIT.THREE_PLUS;
  if (cableCount === 1) limit = OCCUPANCY_LIMITS.CONDUIT.ONE;
  if (cableCount === 2) limit = OCCUPANCY_LIMITS.CONDUIT.TWO;

  for (const conduit of CONDUIT_SIZES) {
    if (totalArea / conduit.internalArea <= limit) {
      return conduit.label;
    }
  }
  return 'N/A';
};

export const getTrayDimension = (totalArea: number, aba: number): number => {
  const requiredPhysicalArea = totalArea / OCCUPANCY_LIMITS.TRAY;
  return getSmallestWidth(requiredPhysicalArea, aba);
};

import React from 'react';
import { CableData, CableForm } from '../types';
import { CABLE_GAUGES } from '../constants';

interface Props {
  cable: CableData;
  onUpdate: (id: string, updates: Partial<CableData>) => void;
  onRemove: (id: string) => void;
}

const CableEntry: React.FC<Props> = ({ cable, onUpdate, onRemove }) => {
  const handleGaugeChange = (val: string) => {
    const gaugeValue = parseFloat(val);
    const found = CABLE_GAUGES.find(g => g.size === gaugeValue);
    if (found) {
      const area = (Math.PI * Math.pow(found.diameter, 2)) / 4;
      onUpdate(cable.id, { 
        gauge: gaugeValue, 
        diameter: found.diameter,
        area: area 
      });
    }
  };

  return (
    <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 mb-3 animate-in fade-in slide-in-from-top-2 duration-300">
      <div className="flex justify-between items-center mb-4">
        <span className="text-xs font-bold uppercase tracking-wider text-blue-600 bg-blue-50 px-2 py-1 rounded">
          {cable.category}
        </span>
        <button 
          onClick={() => onRemove(cable.id)}
          className="text-gray-400 hover:text-red-500 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Formação</label>
          <select 
            value={cable.form}
            onChange={(e) => onUpdate(cable.id, { form: e.target.value as CableForm })}
            className="w-full bg-gray-50 border-gray-200 rounded-lg text-sm focus:ring-blue-500 focus:border-blue-500 p-2"
          >
            <option value="Singelo">Singelo</option>
            <option value="Multipolar">Multipolar</option>
          </select>
        </div>

        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Bitola (mm²)</label>
          <select 
            value={cable.gauge}
            onChange={(e) => handleGaugeChange(e.target.value)}
            className="w-full bg-gray-50 border-gray-200 rounded-lg text-sm focus:ring-blue-500 focus:border-blue-500 p-2"
          >
            {CABLE_GAUGES.map(g => (
              <option key={g.size} value={g.size}>{g.size} mm²</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-xs font-medium text-gray-500 mb-1">Qtd</label>
          <input 
            type="number"
            min="1"
            value={cable.quantity}
            onChange={(e) => onUpdate(cable.id, { quantity: parseInt(e.target.value) || 0 })}
            className="w-full bg-gray-50 border-gray-200 rounded-lg text-sm focus:ring-blue-500 focus:border-blue-500 p-2"
          />
        </div>

        <div className="flex items-end justify-end">
          <div className="text-right">
            <p className="text-[10px] text-gray-400 uppercase leading-none">Subtotal Área</p>
            <p className="text-sm font-semibold text-gray-700">{(cable.area * cable.quantity).toFixed(1)} mm²</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CableEntry;

import React from 'react';
import { STANDARD_ABAS } from '../constants';

