export default ResultCard;

import React, { useState, useMemo, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { CableData, CableType, CableForm } from './types';
import { CABLE_GAUGES, STANDARD_ABAS, OCCUPANCY_LIMITS } from './constants';
import CableEntry from './components/CableEntry';
import ResultCard from './components/ResultCard';
import { getTrayDimension, getConduitSize } from './utils/calculations';

const App: React.FC = () => {
  const [cables, setCables] = useState<CableData[]>([]);
  const [eletrocalhaAba, setEletrocalhaAba] = useState(50);
  const [leitoAba, setLeitoAba] = useState(100);

  const addCable = (category: CableType) => {
    const defaultGauge = CABLE_GAUGES[4]; // 2.5 mm²
    const area = (Math.PI * Math.pow(defaultGauge.diameter, 2)) / 4;

    const newCable: CableData = {
      id: uuidv4(),
      category,
      form: 'Multipolar',
      gauge: defaultGauge.size,
      quantity: 1,
      diameter: defaultGauge.diameter,
      area: area
    };
    setCables([...cables, newCable]);
  };

  const updateCable = (id: string, updates: Partial<CableData>) => {
    setCables(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const removeCable = (id: string) => {
    setCables(prev => prev.filter(c => c.id !== id));
  };

  const totals = useMemo(() => {
    const power = cables.filter(c => c.category === 'Força').reduce((acc, c) => acc + (c.area * c.quantity), 0);
    const control = cables.filter(c => c.category === 'Comando').reduce((acc, c) => acc + (c.area * c.quantity), 0);
    const signal = cables.filter(c => c.category === 'Sinal').reduce((acc, c) => acc + (c.area * c.quantity), 0);
    const totalArea = power + control + signal;
    const totalCount = cables.reduce((acc, c) => acc + c.quantity, 0);

    return { power, control, signal, totalArea, totalCount };
  }, [cables]);

  const results = useMemo(() => {
    const ecWidth = getTrayDimension(totals.totalArea, eletrocalhaAba);
    const lWidth = getTrayDimension(totals.totalArea, leitoAba);
    const condSize = getConduitSize(totals.totalArea, totals.totalCount);

    const ecOccupancy = totals.totalArea > 0 ? (totals.totalArea / (ecWidth * eletrocalhaAba)) * 100 : 0;
    const lOccupancy = totals.totalArea > 0 ? (totals.totalArea / (lWidth * leitoAba)) * 100 : 0;

    return {
      eletrocalha: { width: ecWidth, occupancy: ecOccupancy },
      leito: { width: lWidth, occupancy: lOccupancy },
      eletroduto: { size: condSize }
    };
  }, [totals, eletrocalhaAba, leitoAba]);

  return (
    <div className="min-h-screen pb-10">
      {/* Header */}
      <header className="bg-blue-700 text-white p-6 shadow-md rounded-b-[2rem] sticky top-0 z-50">
        <div className="max-w-md mx-auto flex justify-between items-center">
          <div>
            <h1 className="text-xl font-black">InfraDimension</h1>
            <p className="text-xs text-blue-200 uppercase tracking-widest font-bold">NBR 5410 Sizing Tool</p>
          </div>
          <div className="text-right">
            <p className="text-[10px] text-blue-200 uppercase">Área Total Ocupada</p>
            <p className="text-2xl font-black">{totals.totalArea.toFixed(1)} <span className="text-xs font-normal">mm²</span></p>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto p-4 -mt-4 space-y-6">

        {/* Input Section */}
        <section>
          <div className="flex items-center justify-between mb-4 px-2">
            <h2 className="font-bold text-gray-600 uppercase text-xs tracking-wider">Lançamento de Cabos</h2>
          </div>

          <div className="grid grid-cols-3 gap-2 mb-6">
            {(['Força', 'Comando', 'Sinal'] as CableType[]).map((type) => (
              <button
                key={type}
                onClick={() => addCable(type)}
                className="flex flex-col items-center justify-center p-3 bg-white border-2 border-transparent hover:border-blue-500 rounded-2xl shadow-sm transition-all active:scale-95"
              >
                <div className={`p-2 rounded-full mb-1 ${type === 'Força' ? 'bg-red-50 text-red-500' : type === 'Comando' ? 'bg-blue-50 text-blue-500' : 'bg-green-50 text-green-500'}`}>
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
                  </svg>
                </div>
                <span className="text-[10px] font-bold uppercase">{type}</span>
              </button>
            ))}
          </div>

          <div className="space-y-3">
            {cables.length === 0 ? (
              <div className="text-center py-10 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200">
                <p className="text-gray-400 text-sm">Nenhum cabo adicionado.<br/>Selecione uma categoria acima.</p>
              </div>
            ) : (
              cables.map((cable) => (
                <CableEntry 
                  key={cable.id} 
                  cable={cable} 
                  onUpdate={updateCable} 
                  onRemove={removeCable} 
                />
              ))
            )}
          </div>
        </section>

        {/* Results Section */}
        <section className="space-y-4">
          <h2 className="font-bold text-gray-600 uppercase text-xs tracking-wider px-2">Dimensionamento Calculado</h2>

          <div className="grid grid-cols-1 gap-4">
            <ResultCard 
              title="Eletrocalha" 
              type="Eletrocalha"
              totalArea={totals.totalArea}
              width={results.eletrocalha.width}
              aba={eletrocalhaAba}
              onAbaChange={setEletrocalhaAba}
              occupancy={results.eletrocalha.occupancy}
            />

            <ResultCard 
              title="Leito Porta Cabos" 
              type="Leito"
              totalArea={totals.totalArea}
              width={results.leito.width}
              aba={leitoAba}
              onAbaChange={setLeitoAba}
              occupancy={results.leito.occupancy}
            />

            <ResultCard 
              title="Eletroduto" 
              type="Eletroduto"
              totalArea={totals.totalArea}
              conduitSize={results.eletroduto.size}
              occupancy={totals.totalArea > 0 ? (totals.totalArea / 8494) * 100 : 0} // Visualization against 4" max
            />
          </div>
        </section>

        {/* Footer Info */}
        <footer className="px-4 py-6">
          <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-xl">
            <div className="flex items-start">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-yellow-600 mr-2 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
              </svg>
              <div className="text-[10px] text-yellow-800 leading-relaxed uppercase font-semibold">
                Normas de Referência: NBR-5410<br/>
                Ocupação Eletrodutos: 1c: 53% | 2c: 31% | 3+c: 40%<br/>
                Ocupação Calhas/Leitos: Máx 40% (Recomendado)
              </div>
            </div>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;

