import React from 'react';

interface Props {
  title: string;
  type: 'Eletrocalha' | 'Leito' | 'Eletroduto';
  totalArea: number;
  width?: number;
  aba?: number;
  conduitSize?: string;
  onAbaChange?: (val: number) => void;
  availableAbas?: number[];
  occupancy: number;
}

const ResultCard: React.FC<Props> = ({ 
  title, 
  type, 
  totalArea, 
  width, 
  aba, 
  conduitSize, 
  onAbaChange, 
  availableAbas = [],
  occupancy 
}) => {
  const isConduit = type === 'Eletroduto';

  return (
    <div className="bg-white rounded-2xl p-5 shadow-lg border border-gray-100 flex flex-col h-full">
      <div className="flex items-center justify-between mb-4">
        <h3 className="font-bold text-gray-800 text-lg">{title}</h3>
        <div className={`p-2 rounded-lg ${isConduit ? 'bg-orange-100 text-orange-600' : 'bg-green-100 text-green-600'}`}>
          {isConduit ? (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01" />
