export type CableType = 'Força' | 'Comando';
export type CableForm = 'Singelo' | 'Multipolar';

export interface CableData {
  id: string;
  category: CableType;
  form: CableForm;
  cores?: number; // Number of conductors (e.g., 4 in 4x2.5mm)
  gauge: number; // mm² per core
  quantity: number; // How many cables of this spec
  diameter: number; // External diameter of the whole cable (mm)
  area: number; // Cross-sectional area of the whole cable (mm²)
}

export interface DimensionResult {
  type: 'Eletrocalha' | 'Leito' | 'Eletroduto';
  aba: number;
  largura: number;
  ocupacao: number;
  areaTotalOcupada: number;
}

export interface StandardGauge {
  size: number;
  diameter: number; // Diameter of a single core
}

import { STANDARD_WIDTHS, OCCUPANCY_LIMITS, CONDUIT_SIZES, CABLE_GAUGES } from '../constants';

/**
 * Estimates the external diameter of a multipolar cable based on the diameter of a single core.
 * Uses a heuristic multiplier based on the number of cores plus a factor for insulation/jacket.
 */
export const estimateMultipolarDiameter = (singleCoreDia: number, cores: number | undefined): number => {
  if (!cores || cores <= 1) return singleCoreDia;
  // Standard factor: approx D_core * (sqrt(N) * 1.15) 
  // This accounts for the geometry of the bundle and the outer jacket.
  const factor = Math.sqrt(cores) * 1.18; 
  return singleCoreDia * factor;
};

export const calculateEffectiveArea = (gauge: number, cores: number | undefined, isMultipolar: boolean): { diameter: number, area: number } => {
  const found = CABLE_GAUGES.find(g => g.size === gauge);
  const singleCoreDia = found ? found.diameter : 0;

  if (isMultipolar && !cores) {
    return { diameter: 0, area: 0 };
  }

  const finalDiameter = isMultipolar 
    ? estimateMultipolarDiameter(singleCoreDia, cores) 
    : singleCoreDia;

  const area = (Math.PI * Math.pow(finalDiameter, 2)) / 4;

  return { diameter: finalDiameter, area };
};

export const getSmallestWidth = (requiredArea: number, aba: number): number => {
  for (const width of STANDARD_WIDTHS) {
    if (width * aba >= requiredArea) {
      return width;
    }
  }
  return STANDARD_WIDTHS[STANDARD_WIDTHS.length - 1];
};

export const getConduitSize = (totalArea: number, cableCount: number): string => {
  if (totalArea === 0) return '-';
  let limit = OCCUPANCY_LIMITS.CONDUIT.THREE_PLUS;
  if (cableCount === 1) limit = OCCUPANCY_LIMITS.CONDUIT.ONE;
  if (cableCount === 2) limit = OCCUPANCY_LIMITS.CONDUIT.TWO;

  for (const conduit of CONDUIT_SIZES) {
    if (totalArea / conduit.internalArea <= limit) {
      return conduit.label;
    }
  }
  return 'N/A';
};

export const getTrayDimension = (totalArea: number, aba: number): number => {
  if (totalArea === 0) return 0;
  const requiredPhysicalArea = totalArea / OCCUPANCY_LIMITS.TRAY;
  return getSmallestWidth(requiredPhysicalArea, aba);
};

