export type CableType = 'Força' | 'Comando';
export type CableForm = 'Singelo' | 'Multipolar';
export type InsulationType = '750V' | '1kV';

export interface CableData {
  id: string;
  category: CableType;
  form: CableForm;
  cores?: number;
  gauge: number;
  quantity: number;
  diameter: number;
  area: number;
}

export interface DimensionResult {
  type: 'Eletrocalha' | 'Leito' | 'Eletroduto';
  aba: number;
  largura: number;
  ocupacao: number;
  areaTotalOcupada: number;
}

export interface StandardGauge {
  size: number;
  diameter: number;
}

import { STANDARD_WIDTHS, OCCUPANCY_LIMITS, CONDUIT_SIZES, DIAMETERS_1KV, DIAMETERS_750V } from '../constants';
import { InsulationType } from '../types';

export const getDiameterFromTable = (
  insulation: InsulationType,
  gauge: number,
  cores: number | undefined,
  isMultipolar: boolean
): number => {
  const table = insulation === '1kV' ? DIAMETERS_1KV : DIAMETERS_750V;

  if (!isMultipolar) {
    const val = (table.unipolar as any)[gauge];
    if (val) return val;
    // Fallback heurístico se não estiver na tabela unipolar
    return Math.sqrt(gauge) * 2;
  }

  if (isMultipolar && cores) {
    const coreTable = (table.multipolar as any)[cores];
    if (coreTable) {
      const val = coreTable[gauge];
      if (val) return val;
    }
    // Fallback heurístico para multipolares não mapeados (ex: comandos com muitas vias)
    const singleCoreDia = (table.unipolar as any)[gauge] || Math.sqrt(gauge) * 1.5;
    const factor = Math.sqrt(cores) * 1.15;
    return singleCoreDia * factor;
  }

  return 0;
};

export const calculateEffectiveArea = (
  insulation: InsulationType,
  gauge: number, 
  cores: number | undefined, 
  isMultipolar: boolean
): { diameter: number, area: number } => {
  if (isMultipolar && !cores) {
    return { diameter: 0, area: 0 };
  }

  const finalDiameter = getDiameterFromTable(insulation, gauge, cores, isMultipolar);
  const area = (Math.PI * Math.pow(finalDiameter, 2)) / 4;

  return { diameter: finalDiameter, area };
};

export const getSmallestWidth = (requiredArea: number, aba: number): number => {
  for (const width of STANDARD_WIDTHS) {
    if (width * aba >= requiredArea) {
      return width;
    }
  }
  return STANDARD_WIDTHS[STANDARD_WIDTHS.length - 1];
};

export const getConduitSize = (totalArea: number, cableCount: number): string => {
  if (totalArea === 0) return '-';
  let limit = OCCUPANCY_LIMITS.CONDUIT.THREE_PLUS;
  if (cableCount === 1) limit = OCCUPANCY_LIMITS.CONDUIT.ONE;
  if (cableCount === 2) limit = OCCUPANCY_LIMITS.CONDUIT.TWO;

  for (const conduit of CONDUIT_SIZES) {
    if (totalArea / conduit.internalArea <= limit) {
      return conduit.label;
    }
  }
  return 'N/A';
};

export const getTrayDimension = (totalArea: number, aba: number): number => {
  if (totalArea === 0) return 0;
  const requiredPhysicalArea = totalArea / OCCUPANCY_LIMITS.TRAY;
  return getSmallestWidth(requiredPhysicalArea, aba);
};

import React, { useEffect } from 'react';
import { CableData, CableForm, InsulationType } from '../types';
import { CABLE_GAUGES, COMMAND_GAUGES, MULTI_CORE_OPTIONS_FULL, MULTI_CORE_OPTIONS_POWER } from '../constants';
import { calculateEffectiveArea } from '../utils/calculations';

interface Props {
  cable: CableData;
  insulation: InsulationType;
  onUpdate: (id: string, updates: Partial<CableData>) => void;
  onRemove: (id: string) => void;
}

const CableEntry: React.FC<Props> = ({ cable, insulation, onUpdate, onRemove }) => {
  const gaugesToDisplay = cable.category === 'Comando' 
    ? CABLE_GAUGES.filter(g => COMMAND_GAUGES.includes(g.size))
    : CABLE_GAUGES;

  const coreOptions = cable.category === 'Força' 
    ? MULTI_CORE_OPTIONS_POWER 
    : MULTI_CORE_OPTIONS_FULL;

  // Atualiza quando a isolação global mudar
  useEffect(() => {
    const { diameter, area } = calculateEffectiveArea(
      insulation,
      cable.gauge,
      cable.cores,
      cable.form === 'Multipolar'
    );
    if (diameter !== cable.diameter) {
      onUpdate(cable.id, { diameter, area });
    }
  }, [insulation]);

  const handleUpdate = (updates: Partial<CableData>) => {
    const nextCable = { ...cable, ...updates };

    // Se mudou de categoria para Força, garantir que cores esteja no limite
    if (updates.category === 'Força' && nextCable.cores && nextCable.cores > 5) {
      nextCable.cores = 5;
      updates.cores = 5;
    }

    if (updates.form === 'Multipolar' && !updates.cores) {
      nextCable.cores = undefined;
    }

    const { diameter, area } = calculateEffectiveArea(
      insulation,
      nextCable.gauge, 
      nextCable.cores, 
      nextCable.form === 'Multipolar'
    );
    onUpdate(cable.id, { ...updates, diameter, area });
  };

  return (
    <div className="bg-white p-5 rounded-[2rem] shadow-sm border border-gray-100 mb-3 animate-in fade-in slide-in-from-top-2 duration-300">
      <div className="flex justify-between items-center mb-4">
        <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${cable.category === 'Força' ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'}`}>
          {cable.category}
        </span>
        <button 
          onClick={() => onRemove(cable.id)}
          className="text-gray-300 hover:text-red-500 transition-colors p-1"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-[10px] font-black text-secondary uppercase mb-1.5 opacity-50 ml-1">Formação</label>
          <select 
            value={cable.form}
            onChange={(e) => handleUpdate({ 
              form: e.target.value as CableForm, 
              cores: e.target.value === 'Singelo' ? 1 : undefined 
            })}
            className="w-full bg-gray-50 border-2 border-transparent focus:border-primary rounded-xl text-sm font-bold text-secondary p-3 appearance-none transition-all"
          >
            <option value="Singelo">Singelo</option>
            <option value="Multipolar">Multipolar</option>
          </select>
        </div>

        {cable.form === 'Multipolar' && (
          <div>
            <label className="block text-[10px] font-black text-secondary uppercase mb-1.5 opacity-50 ml-1">Condutores (Vias)</label>
            <select 
              value={cable.cores || ""}
              onChange={(e) => handleUpdate({ cores: e.target.value === "" ? undefined : parseInt(e.target.value) })}
              className={`w-full bg-gray-50 border-2 border-transparent focus:border-primary rounded-xl text-sm font-bold p-3 appearance-none transition-all ${!cable.cores ? 'text-gray-400' : 'text-secondary'}`}
            >
              <option value="">Selecione...</option>
              {coreOptions.map(n => (
                <option key={n} value={n} className="text-secondary">{n} vias</option>
              ))}
            </select>
          </div>
        )}

        <div className="col-span-1">
          <label className="block text-[10px] font-black text-secondary uppercase mb-1.5 opacity-50 ml-1">Bitola Core</label>
          <select 
            value={cable.gauge}
            onChange={(e) => handleUpdate({ gauge: parseFloat(e.target.value) })}
            className="w-full bg-gray-50 border-2 border-transparent focus:border-primary rounded-xl text-sm font-bold text-secondary p-3 appearance-none transition-all"
          >
            {gaugesToDisplay.map(g => (
              <option key={g.size} value={g.size}>{g.size} mm²</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-[10px] font-black text-secondary uppercase mb-1.5 opacity-50 ml-1">Quantidade</label>
          <input 
            type="number"
            min="1"
            value={cable.quantity}
            onChange={(e) => handleUpdate({ quantity: parseInt(e.target.value) || 0 })}
            className="w-full bg-gray-50 border-2 border-transparent focus:border-primary rounded-xl text-sm font-bold text-secondary p-3 transition-all"
          />
        </div>
      </div>

      <div className="mt-4 pt-4 border-t border-gray-50 flex justify-between items-center">
        <div>
          <p className="text-[9px] font-black text-gray-300 uppercase">Resumo Técnico ({insulation})</p>
          <p className="text-xs font-bold text-secondary">
            {cable.form === 'Multipolar' 
              ? (cable.cores ? `${cable.cores}x${cable.gauge} mm²` : `---x${cable.gauge} mm²`) 
              : `${cable.gauge} mm²`}
            <span className="mx-2 text-gray-200">|</span> 
            Ø ext: {cable.diameter > 0 ? `${cable.diameter.toFixed(1)}mm` : '--'}
          </p>
        </div>
        <div className="text-right">
          <p className="text-[9px] font-black text-gray-300 uppercase">Subtotal Área</p>
          <p className="text-lg font-black text-primary">{(cable.area * cable.quantity).toFixed(0)} <span className="text-[10px] font-normal">mm²</span></p>
        </div>
      </div>
    </div>
  );
};

export default CableEntry;

import React, { useState, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { CableData, CableType, InsulationType } from './types';
import { CABLE_GAUGES, STANDARD_ABAS } from './constants';
import CableEntry from './components/CableEntry';
import ResultCard from './components/ResultCard';
import { getTrayDimension, getConduitSize, calculateEffectiveArea } from './utils/calculations';

const Logo = () => (
  <div className="flex flex-col items-center">
    <svg width="60" height="40" viewBox="0 0 100 60" fill="none" xmlns="http://www.w3.org/2000/svg" className="drop-shadow-lg">
      <path d="M10 45 L50 15" stroke="#E99C16" strokeWidth="5" strokeLinecap="round" />
      <path d="M40 55 L80 25" stroke="#E99C16" strokeWidth="5" strokeLinecap="round" />
      <path d="M22 36 L52 46" stroke="#E99C16" strokeWidth="3" strokeLinecap="round" opacity="0.9" />
      <path d="M30 30 L60 40" stroke="#E99C16" strokeWidth="3" strokeLinecap="round" opacity="0.9" />
      <path d="M38 24 L68 34" stroke="#E99C16" strokeWidth="3" strokeLinecap="round" opacity="0.9" />
      <path d="M46 18 L76 28" stroke="#E99C16" strokeWidth="3" strokeLinecap="round" opacity="0.9" />
      <path d="M10 45 L10 49 L50 19 L50 15 Z" fill="#C78512" />
      <path d="M40 55 L40 59 L80 29 L80 25 Z" fill="#C78512" />
    </svg>
    <span className="mestre-energia text-primary text-[8px] mt-0.5 tracking-tighter whitespace-nowrap">Mestre da Energia</span>
  </div>
);

const App: React.FC = () => {
  const [cables, setCables] = useState<CableData[]>([]);
  const [eletrocalhaAba, setEletrocalhaAba] = useState(50);
  const [leitoAba, setLeitoAba] = useState(100);
  const [insulation, setInsulation] = useState<InsulationType>('1kV');

  const addCable = (category: CableType) => {
    const defaultGauge = category === 'Comando' ? 1.0 : 2.5;
    const defaultForm = 'Singelo';
    const defaultCores = 1; 
    const { diameter, area } = calculateEffectiveArea(insulation, defaultGauge, defaultCores, false);

    const newCable: CableData = {
      id: uuidv4(),
      category,
      form: defaultForm,
      cores: defaultCores,
      gauge: defaultGauge,
      quantity: 1,
      diameter,
      area
    };
    setCables([...cables, newCable]);
  };

  const updateCable = (id: string, updates: Partial<CableData>) => {
    setCables(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const removeCable = (id: string) => {
    setCables(prev => prev.filter(c => c.id !== id));
  };

  const totals = useMemo(() => {
    const totalArea = cables.reduce((acc, c) => acc + (c.area * c.quantity), 0);
    const totalCount = cables.reduce((acc, c) => acc + c.quantity, 0);
    return { totalArea, totalCount };
  }, [cables]);

  const results = useMemo(() => {
    const ecWidth = getTrayDimension(totals.totalArea, eletrocalhaAba);
    const calculatedLWidth = getTrayDimension(totals.totalArea, leitoAba);
    const lWidth = Math.max(200, calculatedLWidth);
    const condSize = getConduitSize(totals.totalArea, totals.totalCount);

    const ecOccupancy = totals.totalArea > 0 ? (totals.totalArea / (ecWidth * eletrocalhaAba)) * 100 : 0;
    const lOccupancy = totals.totalArea > 0 ? (totals.totalArea / (lWidth * leitoAba)) * 100 : 0;

    return {
      eletrocalha: { width: ecWidth, occupancy: ecOccupancy },
      leito: { width: lWidth, occupancy: lOccupancy },
      eletroduto: { size: condSize }
    };
  }, [totals, eletrocalhaAba, leitoAba]);

  return (
    <div className="min-h-screen pb-10 bg-gray-50">
      <header className="bg-secondary text-white p-5 shadow-xl rounded-b-[2.5rem] sticky top-0 z-50">
        <div className="max-w-md mx-auto space-y-4">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Logo />
              <div className="border-l border-white/20 pl-3">
                <h1 className="text-sm font-black leading-tight text-primary uppercase">Calculadora de<br/>Infraestrutura</h1>
                <p className="text-[9px] text-white/60 uppercase tracking-widest font-bold">NBR 5410</p>
              </div>
            </div>
            <div className="text-right">
              <p className="text-[9px] text-primary uppercase font-bold mb-0.5">Área Total</p>
              <p className="text-xl font-black">{totals.totalArea.toFixed(1)} <span className="text-[10px] font-normal text-white/40">mm²</span></p>
            </div>
          </div>

          <div className="bg-white/5 p-1 rounded-2xl flex items-center">
            <button 
              onClick={() => setInsulation('750V')}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-wider rounded-xl transition-all ${insulation === '750V' ? 'bg-primary text-secondary shadow-lg' : 'text-white/40 hover:text-white'}`}
            >
              Cabo 450/750V
            </button>
            <button 
              onClick={() => setInsulation('1kV')}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-wider rounded-xl transition-all ${insulation === '1kV' ? 'bg-primary text-secondary shadow-lg' : 'text-white/40 hover:text-white'}`}
            >
              Cabo 0.6/1kV
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-md mx-auto p-4 space-y-6">
        <section>
          <div className="flex items-center justify-between mb-4 px-2">
            <h2 className="font-bold text-secondary uppercase text-xs tracking-wider">Lançamento de Cabos</h2>
          </div>

          <div className="grid grid-cols-2 gap-3 mb-6">
            {(['Força', 'Comando'] as CableType[]).map((type) => (
              <button
                key={type}
                onClick={() => addCable(type)}
                className="flex flex-col items-center justify-center p-5 bg-white border-b-4 border-primary/20 hover:border-primary rounded-[2rem] shadow-sm transition-all active:scale-95 group"
              >
                <div className={`p-3 rounded-full mb-1 transition-colors ${type === 'Força' ? 'bg-red-50 text-red-500' : 'bg-blue-50 text-blue-500'} group-hover:bg-primary group-hover:text-white`}>
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 5a1 1 0 011 1v3h3a1 1 0 110 2h-3v3a1 1 0 11-2 0v-3H6a1 1 0 110-2h3V6a1 1 0 011-1z" clipRule="evenodd" />
                  </svg>
                </div>
                <span className="text-[10px] font-black uppercase text-secondary tracking-wide">{type}</span>
              </button>
            ))}
          </div>

          <div className="space-y-3">
            {cables.length === 0 ? (
              <div className="text-center py-10 bg-white rounded-[2.5rem] border-2 border-dashed border-gray-200">
                <p className="text-gray-400 text-xs font-medium uppercase tracking-widest">Clique acima para lançar cabos</p>
              </div>
            ) : (
              cables.map((cable) => (
                <CableEntry 
                  key={cable.id} 
                  cable={cable}
                  insulation={insulation}
                  onUpdate={updateCable} 
                  onRemove={removeCable} 
                />
              ))
            )}
          </div>
        </section>

        <section className="space-y-4">
          <h2 className="font-bold text-secondary uppercase text-xs tracking-wider px-2">Dimensionamento Calculado</h2>

          <div className="grid grid-cols-1 gap-4">
            <ResultCard 
              title="Eletrocalha" 
              type="Eletrocalha"
              totalArea={totals.totalArea}
              width={results.eletrocalha.width}
              aba={eletrocalhaAba}
              onAbaChange={setEletrocalhaAba}
              availableAbas={STANDARD_ABAS}
              occupancy={results.eletrocalha.occupancy}
            />

            <ResultCard 
              title="Leito Porta Cabos" 
              type="Leito"
              totalArea={totals.totalArea}
              width={results.leito.width}
              aba={leitoAba}
              onAbaChange={setLeitoAba}
              availableAbas={STANDARD_ABAS.filter(a => a >= 100)}
              occupancy={results.leito.occupancy}
            />

            <ResultCard 
              title="Eletroduto" 
              type="Eletroduto"
              totalArea={totals.totalArea}
              conduitSize={results.eletroduto.size}
              occupancy={totals.totalArea > 0 ? (totals.totalArea / 8494) * 100 : 0}
            />
          </div>
        </section>

        <footer className="px-4 py-8">
          <div className="bg-secondary p-5 rounded-2xl shadow-lg relative overflow-hidden flex justify-center items-center">
            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full -mr-16 -mt-16"></div>
            <span className="mestre-energia text-[10px] text-white/30 tracking-widest relative z-10">© Mestre da Energia</span>
          </div>
        </footer>
      </main>
    </div>
  );
};

export default App;
